from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Auto_sw_update(EmssimCommand):

    def __init__(self, method="auto_sw_update -enable", timeout=60, rpc_connection_name='localRPC'):
        super(Auto_sw_update, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Auto_sw_update, self).on_new_data(**data)
        if 'info' in data:
            self._ret = data
